// The new app on documents shaped exactly as the stable app wrote them
// (tools/backtest/app/fixtures: old_app_docs.json is generated by the base
// build's own encoders, hand_docs.json holds shapes no harness encoder makes).
import 'package:cgpa_calculator/core/heads/heads.dart';
import 'package:cgpa_calculator/core/heads/paths.dart';
import 'package:cgpa_calculator/core/reviews/gate_store.dart';
import 'package:cgpa_calculator/core/roles/capabilities.dart';
import 'package:cgpa_calculator/core/roles/contacts.dart';
import 'package:cgpa_calculator/core/roles/role_store.dart';
import 'package:cgpa_calculator/core/roles/roles.dart';
import 'package:cgpa_calculator/core/search/hints.dart';
import 'package:fake_cloud_firestore/fake_cloud_firestore.dart';
import 'package:flutter_test/flutter_test.dart';

import 'common/support.dart';

void main() {
  late FakeFirebaseFirestore db;
  setUp(() async {
    final docs = {...fixture('old_app_docs.json'), ...fixture('hand_docs.json')}
      ..remove('_comment');
    db = await seeded(docs);
  });
  RoleStore as(String e) => RoleStore(db, me: e, myName: 'x');
  final now = DateTime(2026, 11, 23);

  test('every old grant and staff document parses', () async {
    final g = await db.collection('grants').get();
    expect(g.docs.length, greaterThan(5));
    for (final d in g.docs) {
      expect(() => Grant.fromMap(d.data()), returnsNormally, reason: d.id);
    }
    for (final d in (await db.collection('staff').get()).docs) {
      final s = StaffEntry.fromMap(d.data());
      expect(s.reach, isEmpty, reason: 'old builds wrote no reach');
    }
  });

  test('loadMine: roles, defaults when roles/ is absent', () async {
    final pres = await as('f20239992@goa.bits-pilani.ac.in').loadMine(now: now);
    expect(pres.grants.single.role, GrantRole.dept);
    expect(pres.custom, isNull);
    expect(pres.roleDefs['president']!.caps, defaultBuiltinCaps()['president']);
    expect(
      pres.may(Capability.courseStructures, campus: 'goa', scope: 'ELEC'),
      isTrue,
    );
    expect(
      pres.may(Capability.courseStructures, campus: 'goa', scope: 'CS'),
      isFalse,
    );
    final adm = await as(
      'f20209991@pilani.bits-pilani.ac.in',
    ).loadMine(now: now);
    expect(adm.admin, isTrue);
    expect(adm.reachesAdmin, isTrue);
    final own = await as('owner@pointer.test').loadMine(now: now);
    expect(own.owner, isTrue);
    expect(own.roleDefs['admin']!.termDays, 730);
    for (final gone in [
      'f20219998@goa.bits-pilani.ac.in', // expired president
      'f20249995@goa.bits-pilani.ac.in', // revoked CR
      'f20249994@goa.bits-pilani.ac.in', // plain student
    ]) {
      final r = await as(gone).loadMine(now: now);
      expect(
        [r.grants.length, r.owner, r.custom == null],
        [0, false, true],
        reason: gone,
      );
    }
    final contrib = await as(
      'f20249911@goa.bits-pilani.ac.in',
    ).loadMine(now: now);
    expect([contrib.contributor, contrib.grants.length], [true, 0]);
    final early = await as(
      'f20249912@goa.bits-pilani.ac.in',
    ).loadMine(now: now);
    expect(
      early.courses.single.scope,
      'EEE F111',
      reason: 'expiresAt as millis',
    );
  });

  test('config/grantTerms alone stays authoritative for the terms', () async {
    final s = as('owner@pointer.test');
    expect(await s.terms(), (crDays: 183, presidentDays: 365, adminDays: 730));
    final e = await s.rolesForEdit();
    expect(e.saved, isFalse);
    expect(e.defs['cr']!.termDays, 183);
    await db.collection('config').doc('grantTerms').set({
      'crDays': 90,
      'presidentDays': 200,
      'adminDays': 300,
    });
    final e2 = await as('owner@pointer.test').rolesForEdit();
    expect((e2.defs['cr']!.termDays, e2.defs['admin']!.termDays), (90, 300));
  });

  test('gate doc with dept, heads without the roles marker, roster', () async {
    final s = as('f20249994@goa.bits-pilani.ac.in');
    expect(await GateStore(s).of('goa'), isTrue);
    final h = Head.fromMap((await db.doc('heads/goa').get()).data()!);
    expect(h.version(Paths.roles), isNull);
    expect(await s.roleDefs(), isNotNull);
    final r = await as('owner@pointer.test').roster(campus: 'goa');
    expect(r.where((g) => g.role == GrantRole.admin), isNotEmpty);
  });

  test('search hints: old vote counts still widen the query', () async {
    final m = await SearchHints(db).load('goa');
    expect(alsoSearch('oel', m), contains('open elective'));
    expect(alsoSearch('oe', m), isNot(contains('open elective')));
  });

  test('old directory entry reads', () async {
    final d = DirectoryEntry.fromMap(
      'f20239992@goa.bits-pilani.ac.in',
      (await db.doc('directory/f20239992@goa.bits-pilani.ac.in').get()).data()!,
    );
    expect(d.roles.single.role, GrantRole.dept);
  });
}
